/**
 * The 118 elements, parsed from PubChem's periodic table (pubchemElements.ts,
 * generated by scripts/fetch_periodic_table.mjs). Nothing here is typed in by
 * hand: every value shown to a student is PubChem's, and the only things this
 * file adds are DERIVED from the atomic number (group, period, grid position)
 * or converted (kelvin to Celsius).
 *
 * Source: PubChem Periodic Table, NCBI, public domain,
 * https://pubchem.ncbi.nlm.nih.gov/periodic-table/
 *
 * Categories are PubChem's GroupBlock, which is close to the ptable.com and RSC
 * grouping: it lists halogens apart from the other nonmetals, and it puts
 * lanthanum to lutetium and actinium to lawrencium in the two f rows, which is
 * how the RSC table draws them (15 wide, with a "57-71" marker in group 3).
 */

import { PUBCHEM_ROWS } from "./pubchemElements";

export type Category =
  | "alkali"
  | "alkaline"
  | "transition"
  | "post_transition"
  | "metalloid"
  | "nonmetal"
  | "halogen"
  | "noble"
  | "lanthanide"
  | "actinide";

/** PubChem's StandardState, folded: "Expected to be a Gas" becomes predicted. */
export type Phase = "solid" | "liquid" | "gas" | "predicted";

export interface Element {
  readonly number: number;
  readonly symbol: string;
  readonly name: string;
  /** PubChem's AtomicMass string, kept as text so trailing digits survive. */
  readonly mass: string;
  readonly category: Category;
  /** 1 to 18, or null for the two f rows. Derived from the atomic number. */
  readonly group: number | null;
  readonly period: number;
  readonly electronegativity: number | null;
  readonly configuration: string;
  readonly atomicRadiusPm: number | null;
  readonly ionizationEnergyEv: number | null;
  readonly electronAffinityEv: number | null;
  readonly oxidationStates: string;
  readonly phase: Phase;
  readonly meltingPointK: number | null;
  readonly boilingPointK: number | null;
  readonly densityGPerCm3: number | null;
  readonly yearDiscovered: string;
}

export const CATEGORY_LABEL: Record<Category, string> = {
  alkali: "Alkali metal",
  alkaline: "Alkaline earth metal",
  transition: "Transition metal",
  post_transition: "Post-transition metal",
  metalloid: "Metalloid",
  nonmetal: "Nonmetal",
  halogen: "Halogen",
  noble: "Noble gas",
  lanthanide: "Lanthanide",
  actinide: "Actinide",
};

/** The order categories appear in, left to right across the table. */
export const CATEGORIES: readonly Category[] = [
  "alkali",
  "alkaline",
  "transition",
  "post_transition",
  "metalloid",
  "nonmetal",
  "halogen",
  "noble",
  "lanthanide",
  "actinide",
];

const GROUP_BLOCK: Record<string, Category> = {
  "Alkali metal": "alkali",
  "Alkaline earth metal": "alkaline",
  "Transition metal": "transition",
  "Post-transition metal": "post_transition",
  Metalloid: "metalloid",
  Nonmetal: "nonmetal",
  Halogen: "halogen",
  "Noble gas": "noble",
  Lanthanide: "lanthanide",
  Actinide: "actinide",
};

/** The last atomic number of each period: the noble gases. */
const PERIOD_ENDS = [2, 10, 18, 36, 54, 86, 118];

/**
 * Period and group from the atomic number alone, which is the aufbau shape of
 * the table: 2, 8, 8, 18, 18, 32, 32 elements per period. In periods 6 and 7
 * the third to seventeenth elements (La to Lu, Ac to Lr) are the f rows and
 * get no group.
 */
export function periodAndGroup(number: number): { readonly period: number; readonly group: number | null } {
  const period = PERIOD_ENDS.findIndex((end) => number <= end) + 1;
  if (period === 0) throw new Error(`no period for atomic number ${number}`);
  const offset = number - (period === 1 ? 1 : PERIOD_ENDS[period - 2] + 1);
  if (period === 1) return { period, group: number === 1 ? 1 : 18 };
  if (period <= 3) return { period, group: offset < 2 ? offset + 1 : offset + 11 };
  if (period <= 5) return { period, group: offset + 1 };
  if (offset < 2) return { period, group: offset + 1 };
  if (offset <= 16) return { period, group: null };
  return { period, group: offset - 13 };
}

/** PubChem leaves a cell empty when it has no value. */
function numberOrNull(text: string): number | null {
  if (text.trim() === "") return null;
  const value = Number(text);
  return Number.isFinite(value) ? value : null;
}

function parsePhase(text: string): Phase {
  if (text.startsWith("Expected")) return "predicted";
  if (text === "Solid") return "solid";
  if (text === "Liquid") return "liquid";
  if (text === "Gas") return "gas";
  throw new Error(`unknown PubChem StandardState ${text}`);
}

export const ELEMENTS: readonly Element[] = Object.freeze(
  PUBCHEM_ROWS.map((cells) => {
    // Column order is PUBCHEM_COLUMNS in pubchemElements.ts.
    const [number, symbol, name, mass, , configuration, electronegativity, radius, ionization, affinity, oxidation, state, melting, boiling, density, groupBlock, year] = cells;
    const category = GROUP_BLOCK[groupBlock];
    if (category === undefined) throw new Error(`unknown PubChem GroupBlock ${groupBlock}`);
    const z = Number(number);
    const { period, group } = periodAndGroup(z);
    return Object.freeze({
      number: z,
      symbol,
      name,
      mass,
      category,
      group,
      period,
      electronegativity: numberOrNull(electronegativity),
      configuration,
      atomicRadiusPm: numberOrNull(radius),
      ionizationEnergyEv: numberOrNull(ionization),
      electronAffinityEv: numberOrNull(affinity),
      oxidationStates: oxidation,
      phase: parsePhase(state),
      meltingPointK: numberOrNull(melting),
      boilingPointK: numberOrNull(boiling),
      densityGPerCm3: numberOrNull(density),
      yearDiscovered: year,
    });
  }),
);

export function elementBySymbol(symbol: string): Element | null {
  const key = symbol.toLowerCase();
  return ELEMENTS.find((element) => element.symbol.toLowerCase() === key) ?? null;
}

/**
 * Grid placement: 18 columns, rows 1 to 7 for the periods, row 8 a spacer, and
 * rows 9 and 10 for the f rows, columns 3 to 17 (RSC layout). Group 3 of
 * periods 6 and 7 holds the "57-71" and "89-103" markers instead.
 */
export function gridPosition(element: Element): { readonly column: number; readonly row: number } {
  if (element.group !== null) return { column: element.group, row: element.period };
  const first = element.period === 6 ? 57 : 89;
  return { column: element.number - first + 3, row: element.period === 6 ? 9 : 10 };
}

/** Kelvin to Celsius, rounded to one decimal place for display. */
export function kelvinToCelsius(kelvin: number): number {
  return Math.round((kelvin - 273.15) * 10) / 10;
}

/** Atomic mass rounded to three decimals for the tiles; the detail card shows PubChem's full string. */
export function shortMass(mass: string): string {
  return String(Number.parseFloat(Number(mass).toFixed(3)));
}
